```yaml
name: PR Closer

on:
  schedule:
    - cron: '0 0 * * *'  # Runs daily at midnight UTC
  workflow_dispatch:

permissions:
  pull-requests: write
  contents: read

jobs:
  close-prs:
    runs-on: ubuntu-latest
    steps:
      - name: Close stale PRs
        uses: actions/github-script@v6
        with:
          script: |
            const days30 = 30;
            const now = new Date();
            const threshold = new Date(now.getTime() - days30 * 24 * 60 * 60 * 1000);
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            const prList = await octokit.paginate(octokit.pulls.list, {
              owner,
              repo,
              state: 'open',
              per_page: 100
            });

            for (const pr of prList) {
              const createdAt = new Date(pr.created_at);
              if (createdAt > threshold) continue;          // Not old enough
              if (pr.user.login === 'jdx') continue;        // Authored by maintainer
              const hasKeepOpen = pr.labels.some(label => label.name === 'keep-open');
              if (hasKeepOpen) continue;                    // Labeled to keep open

              // Close the PR
              await octokit.pulls.update({
                owner,
                repo,
                pull_number: pr.number,
                state: 'closed'
              });

              // Add a comment explaining the closure
              await octokit.issues.createComment({
                owner,
                repo,
                issue_number: pr.number,
                body: 'This PR has been automatically closed due to inactivity. If you wish to reopen, please comment or open a new PR.'
              });

              console.log(`Closed PR #${pr.number}`);
            }
```

